package fr.crewcmoi.teleport.gui;
import fr.crewcmoi.Main; import fr.crewcmoi.other.utils.GuiItems; import fr.crewcmoi.other.utils.MoneyFormat; import fr.crewcmoi.teleport.managers.HomeManager; import org.bukkit.*; import org.bukkit.entity.Player; import org.bukkit.inventory.*; import org.bukkit.inventory.meta.ItemMeta; import java.util.*;
public class HomeShopGuiManager { private final Main plugin; private final HomeManager manager; public HomeShopGuiManager(Main p,HomeManager m){plugin=p;manager=m;} public void open(Player p){HomeShopHolder h=new HomeShopHolder();Inventory inv=Bukkit.createInventory(h,54,color("&8&lꜱʜᴏᴘ • ʜᴏᴍᴇꜱ"));h.setInventory(inv);for(int i=0;i<54;i++)inv.setItem(i,GuiItems.nothing(" "));int slots=manager.getMaxHomes(p.getUniqueId());double price=plugin.getConfig().getDouble("homes.base-price",5000)+Math.max(0,slots-1)*plugin.getConfig().getDouble("homes.price-increment",5000);ItemStack buy=new ItemStack(Material.ENDER_CHEST);ItemMeta m=buy.getItemMeta();m.setDisplayName(color("&a&lᴀᴄʜᴇᴛᴇʀ ᴜɴ ꜱʟᴏᴛ ʜᴏᴍᴇ"));m.setLore(Arrays.asList(color("&7ʜᴏᴍᴇꜱ ᴀᴄᴛᴜᴇʟꜱ : &f"+slots),color("&7ᴘʀᴏᴄʜᴀɪɴ ᴘʀɪx : &a"+MoneyFormat.format(price)),"",color("&eᴄʟɪǫᴜᴇᴢ ᴘᴏᴜʀ ᴀᴄʜᴇᴛᴇʀ")));buy.setItemMeta(m);inv.setItem(22,buy);p.openInventory(inv);} public void buy(Player p){int slots=manager.getMaxHomes(p.getUniqueId());double price=plugin.getConfig().getDouble("homes.base-price",5000)+Math.max(0,slots-1)*plugin.getConfig().getDouble("homes.price-increment",5000);manager.purchaseSlot(p,price,ok->{p.sendMessage(color(ok?"&aSlot de home acheté ! Tu peux maintenant utiliser /sethome <nom>.":"&cFonds insuffisants."));if(p.isOnline())open(p);});} private String color(String s){return ChatColor.translateAlternateColorCodes('&',s);} }
